solution:
static class Volume {
    private int level;

    Volume(int level) {
        if (level < 0 || level > 100) {
            throw new IllegalArgumentException("level out of range: " + level);
        }
        this.level = level;
    }

    int level() {
        return level;
    }

    void up(int amount) {
        level = Math.min(100, level + amount);
    }

    void down(int amount) {
        level = Math.max(0, level - amount);
    }
}
